<script setup lang="ts">
import type { ColorLimit, GenerationMode, GenerationSettings, ShortSidePreset } from "../../domain/photo-generation";
defineProps<{ modelValue: GenerationSettings; pending: boolean; busy?: boolean }>();
const emit = defineEmits<{ change: [Partial<GenerationSettings>]; regenerate: [] }>();
const sizes: ShortSidePreset[]=[29,58,87]; const colors: ColorLimit[]=[12,24,36]; const modes: GenerationMode[]=["auto","cartoon","realistic"];
</script>
<template><view class="settings surface-card"><text class="section-title">生成设置</text><view class="row"><text>短边格数</text><button v-for="value in sizes" :key="value" :class="{active:modelValue.shortSide===value}" @tap="emit('change',{shortSide:value})">{{ value }}</button></view><view class="row"><text>颜色数</text><button v-for="value in colors" :key="value" :class="{active:modelValue.colorLimit===value}" @tap="emit('change',{colorLimit:value})">{{ value }}</button></view><view class="row"><text>模式</text><button v-for="value in modes" :key="value" :class="{active:modelValue.mode===value}" @tap="emit('change',{mode:value})">{{ value==='auto'?'自动':value==='cartoon'?'卡通':'写实' }}</button></view><view class="switches"><label><switch :checked="modelValue.removeBackground" @change="emit('change',{removeBackground:!modelValue.removeBackground})"/>去除纯色背景</label><label><switch :checked="modelValue.dithering" @change="emit('change',{dithering:!modelValue.dithering})"/>抖动过渡</label><label><switch :checked="modelValue.cleanupIsolated" @change="emit('change',{cleanupIsolated:!modelValue.cleanupIsolated})"/>清理孤立色</label></view><button v-if="pending" class="regenerate" :disabled="busy" @tap="emit('regenerate')">{{busy?'生成中…':'重新生成'}}</button></view></template>
<style scoped>.settings{padding:28rpx}.section-title{display:block}.row{display:flex;align-items:center;gap:10rpx;margin-top:20rpx}.row>text{width:120rpx;font-size:24rpx}.row button{min-width:80rpx;margin:0;padding:0 12rpx;border-radius:999rpx;font-size:22rpx}.row button.active{color:#fff;background:var(--color-lavender-strong)}.switches{display:grid;gap:14rpx;margin-top:22rpx;font-size:24rpx}.regenerate{margin-top:24rpx;color:#fff;background:var(--color-lavender-strong);border-radius:20rpx}</style>
